'use strict';
/* Tonfunk Zeichnungs-Lab: Daten (ZEI_DATA: Körper, Linienarten, Regeln, Aufgaben, Beispiele; ZEI_TASKS: Kurzliste).
   Körper als Schichten lay[z][r] (z=0 unten; Zeile r=0 ist HINTEN, letzte Zeile ist VORN, so wie in der Draufsicht gezeichnet; '#' = Material).
   holes: Durchgangsbohrungen (im Modell eckig, für die Mittellinien): ax = Achse, from/to = Würfelschichten entlang der Achse.
   u = Millimeter je Würfel (für die Bemaßung der Beispiele). */
(function (root) {
  const models = {
    wuerfel: { title: 'Würfel', lay: [['#']] },
    winkel: { title: 'Winkel mit Bohrung', note: 'Winkel 40 × 30 × 30 mm mit Durchgangsbohrung (hier eckig gezeichnet)',
      lay: [['####', '##.#', '####'], ['#...', '#...', '#...'], ['#...', '#...', '#...']], holes: [{ ax: 'z', x: 2, y: 1, from: 0, to: 1 }] },
    treppe: { title: 'Treppe', note: 'Drei Stufen nebeneinander, nach rechts abfallend', lay: [['###', '###'], ['##.', '##.'], ['#..', '#..']] },
    stufenblock: { title: 'Stufenblock', note: 'Block mit einer Stufe und einem Absatz in der Draufsicht',
      lay: [['####', '####', '####'], ['##..', '#...', '....']] },
    nutenstein: { title: 'Nutenstein', note: 'Breiter Fuß, schmaler Hals, Bohrung durch beide Teile (vereinfacht eckig)',
      lay: [['#####', '##.##', '#####'], ['.###.', '.#.#.', '.###.']], holes: [{ ax: 'z', x: 2, y: 1, from: 0, to: 2 }] },
    prisma: { title: 'Block mit Nut', note: 'Block 40 × 30 × 20 mm mit durchgehender Nut (20 mm breit, 10 mm tief)',
      lay: [['####', '####', '####'], ['#..#', '#..#', '#..#']] },
    bruecke: { title: 'Brücke (Durchgang)', note: 'Block mit durchgehendem Durchbruch quer durch die Tiefe',
      lay: [['#...#', '#...#'], ['#...#', '#...#'], ['#####', '#####']] },
    zapfen: { title: 'Platte mit Zapfen', note: 'Platte 30 × 30 × 10 mm mit mittigem Zapfen',
      lay: [['###', '###', '###'], ['...', '.#.', '...']] },
    staffel: { title: 'Treppenblock', note: 'Block mit Stufen in zwei Richtungen: hinten links am höchsten',
      lay: [['####', '####', '####'], ['###.', '##..', '....'], ['#...', '....', '....']] },
    winkelplatte: { title: 'Eckplatte', note: 'L-förmige Platte, 10 mm dick', lay: [['#..', '#..', '###']] },
    wellenabsatz: { title: 'Wellenabsatz mit Zentrierbohrung', note: 'Stufenwelle (quadratischer Querschnitt statt rund, vereinfacht): dicker Bund 30 mm, Zapfen 10 mm, Zentrierung am Ende',
      lay: [['###...', '###...', '###...'], ['###...', '.#####', '###...'], ['###...', '###...', '###...']], holes: [{ ax: 'x', y: 1, z: 1, from: 0, to: 1 }] }
  };

  /* Linienarten nach DIN EN ISO 128-20 (Kurzform); nr = Linientyp-Nummer */
  const lines = [
    { id: 'breit', name: 'Volllinie breit', nr: '01.2', use: 'Sichtbare Kanten und Umrisse' },
    { id: 'schmal', name: 'Volllinie schmal', nr: '01.1', use: 'Maßlinien, Maßhilfslinien und Schraffuren' },
    /* PRUEFEN: Strichlinie für verdeckte Kanten: 02.1 (schmal) oder 02.2 (breit) erlaubt; Tabellenbuch des Betriebs vergleichen */
    { id: 'strich', name: 'Strichlinie', nr: '02.1 / 02.2', use: 'Verdeckte Kanten und Umrisse' },
    { id: 'sp', name: 'Strich-Punkt-Linie schmal', nr: '04.1', use: 'Mittellinien und Symmetrielinien' },
    /* PRUEFEN: Schnittverlauf breit an Enden und Richtungswechseln (ISO 128-40) */
    { id: 'spb', name: 'Strich-Punkt-Linie breit', nr: '04.2', use: 'Schnittverlauf an den Enden und bei Richtungswechseln' },
    { id: 'frei', name: 'Freihandlinie schmal', nr: '01.1 (freihand)', use: 'Bruchkanten bei abgebrochenen Darstellungen' },
    /* PRUEFEN: Nummer 05.1 */
    { id: 'zwei', name: 'Strich-Zweipunkt-Linie schmal', nr: '05.1', use: 'Umrisse von Nachbarteilen und Grenzstellungen beweglicher Teile' }
  ];

  /* Bemaßungsregeln (nur Regeln, bei denen sichere Quellen übereinstimmen); l = Stufe */
  const rules = [
    { l: 1, q: 'Mit welcher Linienart werden Maßlinien gezeichnet?', right: 'Volllinie schmal', wrong: ['Volllinie breit', 'Strichlinie', 'Strich-Punkt-Linie schmal'], expl: 'Maßlinien und Maßhilfslinien sind Volllinien schmal. Die breite Volllinie ist den sichtbaren Körperkanten vorbehalten.' },
    { l: 2, q: 'Wie stehen Maßhilfslinien zur bemaßten Strecke?', right: 'Rechtwinklig zur Strecke, sie überragen die Maßlinie leicht', wrong: ['Parallel zur Strecke, genau auf der Körperkante liegend', 'Unter 45° zur Strecke, damit man sie von der Kante unterscheidet', 'Sie enden immer genau an der Maßlinie, ohne Überstand'], expl: 'Maßhilfslinien stehen senkrecht auf der bemaßten Strecke und überragen die Maßlinie um etwa 1 bis 2 mm.' },
    { l: 2, q: 'Wie wird die Maßzahl an einer senkrechten Maßlinie geschrieben?', right: 'Links der Maßlinie, um 90° gedreht, von rechts lesbar', wrong: ['Rechts neben der Maßlinie, so dass man sie von links liest', 'Immer waagerecht geschrieben, egal wie die Maßlinie liegt', 'Mitten auf der Maßlinie, dabei auf dem Kopf stehend'], expl: 'Maßzahlen sind von unten oder von rechts lesbar: an waagerechten Maßlinien über der Linie, an senkrechten Maßlinien links davon, um 90° gedreht.' },
    { l: 1, q: 'Welches Zeichen steht vor der Maßzahl eines Kreisdurchmessers?', right: '⌀', wrong: ['R', '□', 'M'], expl: 'Das Zeichen ⌀ steht vor der Maßzahl, wenn ein Durchmesser bemaßt wird, zum Beispiel ⌀12. R steht für den Radius, □ für ein Quadrat.' },
    { l: 1, q: 'Welcher Buchstabe steht vor der Maßzahl eines Radius?', right: 'R', wrong: ['⌀', '□', 'M'], expl: 'Radien werden mit R vor der Maßzahl bemaßt, zum Beispiel R5. Der Radius ist die Hälfte des Durchmessers.' },
    { l: 3, q: 'Wie oft wird ein Maß in einer Zeichnung eingetragen?', right: 'Jedes Maß nur einmal (keine Doppelbemaßung)', wrong: ['In jeder Ansicht noch einmal, damit man es schneller findet', 'Zur Kontrolle immer zweimal'], expl: 'Doppelbemaßung ist zu vermeiden: Jedes Maß steht nur einmal, und zwar in der Ansicht, in der die Form am besten zu erkennen ist.' },
    { l: 3, q: 'Warum lässt man bei einer geschlossenen Maßkette (alle Teilmaße und das Gesamtmaß) ein Maß weg?', right: 'Sonst ist die Zeichnung überbestimmt: Toleranzen addieren sich und widersprechen sich', wrong: ['Weil die Zeichnung sonst zu groß für das Blatt wird', 'Weil man Teilmaße und Gesamtmaß nicht zusammen schreiben darf, wenn sie im Maßstab gezeichnet sind'], expl: 'Sind alle Teilmaße und das Gesamtmaß eingetragen, bestimmt jedes Maß das andere mit. Die Toleranzen widersprechen sich. Deshalb lässt man ein Maß weg oder setzt es als Hilfsmaß in Klammern.' },
    { l: 1, q: 'Welche Einheit gilt, wenn bei den Maßzahlen einer Maschinenbau-Zeichnung keine Einheit steht?', right: 'Millimeter (mm)', wrong: ['Zentimeter (cm)', 'Meter (m)', 'Zoll (inch)'], expl: 'Im Maschinenbau sind Längenmaße in Millimetern angegeben; die Einheit wird nicht eingetragen.' },
    { l: 3, q: 'Ein Bauteil ist 20 mm lang und wird im Maßstab 2:1 gezeichnet. Welche Maßzahl steht an der Maßlinie?', right: '20', wrong: ['40', '10', '2'], expl: 'Die Maßzahl gibt immer das tatsächliche Maß des Bauteils an, unabhängig vom Maßstab. Die gezeichnete Strecke ist dann 40 mm lang, die Zahl bleibt 20.' },
    { l: 2, q: 'Dürfen Körperkanten oder Mittellinien als Maßlinie benutzt werden?', right: 'Nein, sie werden stets extra gezeichnet', wrong: ['Ja, das spart Platz auf dem Zeichenblatt', 'Ja, aber nur bei den breiten Körperkanten'], expl: 'Maßlinien sind eigene Linien (Volllinie schmal). Kanten und Mittellinien dürfen nicht als Maßlinie dienen; Mittellinien dürfen aber als Maßhilfslinie verlängert werden.' },
    /* PRUEFEN: Abstand 10 mm der ersten Maßlinie zur Körperkante (Tabellenbuch: etwa 10 mm, weitere mindestens 7 mm) */
    { l: 2, q: 'Wo wird die erste Maßlinie bevorzugt eingetragen?', right: 'Außerhalb der Ansicht, etwa 10 mm von der Kante', wrong: ['Genau auf der Körperkante der Ansicht liegend', 'Mitten durch die Ansicht quer über alle Körperkanten', 'Dicht an der Kante mit nur 1 mm Abstand'], expl: 'Maße stehen bevorzugt außerhalb der Ansicht. Die erste Maßlinie hat etwa 10 mm Abstand zur Körperkante, weitere mindestens etwa 7 mm.' },
    { l: 3, q: 'Wohin gehören Maße bevorzugt?', right: 'An sichtbare Kanten, nicht an Strichlinien', wrong: ['Nur an verdeckte Kanten, damit die Ansicht übersichtlich bleibt', 'An beliebige Linien, die Linienart ist egal'], expl: 'Bemaße möglichst an sichtbaren Kanten (Volllinien), nicht an verdeckten Kanten. Dafür wählt man die Ansicht oder den Schnitt, in dem die Form sichtbar ist.' },
    { l: 1, q: 'Welches Zeichen steht vor der Maßzahl, wenn die Seitenlänge eines Quadrats bemaßt wird?', right: '□', wrong: ['⌀', 'R', 'M'], expl: 'Das Quadratzeichen □ steht vor der Maßzahl der Seitenlänge, zum Beispiel □20 für ein Quadrat mit 20 mm Seitenlänge. ⌀ gehört zum Durchmesser, R zum Radius.' },
    /* PRUEFEN: Schraffur unter 45° zur Achse oder Hauptkante (ISO 128-50); Winkel und Abstand im Tabellenbuch des Betriebs vergleichen */
    { l: 2, q: 'Wie werden Schraffuren in einem Schnitt gezeichnet?', right: 'Als Volllinien schmal, unter 45° zur Achse', wrong: ['Als Strichlinien, ganz ohne feste Richtung', 'Als Volllinien breit, parallel zur Kante', 'Als Strich-Punkt-Linien in jedem Winkel'], expl: 'Schnittflächen werden mit Volllinien schmal unter 45° schraffiert. Die Linien haben gleichen Abstand und enden an der Umrisslinie der Schnittfläche.' },
    { l: 2, q: 'Wie weit ragen Mittellinien über die Umrisslinie des Bauteils hinaus?', right: 'Ein kurzes Stück über die Kontur hinaus', wrong: ['Sie enden genau auf der Körperkante', 'Sie laufen quer über das ganze Zeichenblatt', 'Sie ragen nie nach außen, sondern bleiben innen'], expl: 'Mittellinien (Strich-Punkt-Linie schmal) überragen die Umrisse ein kurzes Stück. So erkennt man sie gut, und man kann sie bei Bedarf als Maßhilfslinie verlängern.' }
  ];

  const T = (id, cat, level, title, o) => Object.assign({ id, cat, level, title }, o);
  const AN = 'Ansichten', ER = 'Ansichten ergänzen', LB = 'Linien und Bemaßung', MA = 'Maßstab', SC = 'Schnitt', BL = 'Blatt und Schrift', DA = 'Darstellungsarten';
  const ISOHINT = 'Die Isometrie zeigt den Körper von vorn rechts oben: die linke sichtbare Seitenfläche ist die Vorderseite, die Fläche oben die Draufsicht.';
  const tasks = [
    T('zei1', AN, 1, 'Anordnung: Was liegt unter der Vorderansicht?', { kind: 'know', q: 'Welche Ansicht liegt bei der Projektionsmethode 1 (Europa) UNTER der Vorderansicht?', right: 'Die Draufsicht', wrong: ['Die Seitenansicht von links', 'Die Untersicht', 'Die Rückansicht'], tips: ['Die Vorderansicht steht in der Mitte, die anderen Ansichten ordnet man um sie herum an.', 'Die Draufsicht schaut von oben auf den Körper. Sie klappt nach unten weg.'], expl: 'Die Draufsicht liegt unter der Vorderansicht. Die Seitenansicht von links liegt rechts daneben.' }),
    T('zei2', AN, 1, 'Anordnung: Wo liegt die Seitenansicht von links?', { kind: 'know', q: 'Wo wird die Seitenansicht von links bei der Projektionsmethode 1 (Europa) gezeichnet?', right: 'Rechts neben der Vorderansicht', wrong: ['Links neben der Vorderansicht', 'Über der Vorderansicht', 'Unter der Vorderansicht'], tips: ['Merke: In Europa liegt jede Ansicht auf der entgegengesetzten Seite des Blickpunkts.', 'Du blickst von links auf den Körper: die Ansicht wird auf die gegenüberliegende Seite, also nach rechts, gelegt.'], expl: 'Seitenansicht von links: rechts von der Vorderansicht. Draufsicht: darunter. Beide liegen auf der entgegengesetzten Seite des Blickpunkts.' }),
    T('zei3', AN, 1, 'Treppe: Welche Vorderansicht passt?', { kind: 'iso2view', model: 'treppe', view: 'front', text: 'Welche Vorderansicht gehört zum gezeigten Körper? ' + ISOHINT, tips: ['Schau von vorn auf die linke sichtbare Seitenfläche. Zähle die Stufen und ihre Höhen.', 'Von vorn sehen die Stufen aus wie eine Treppe: links niedrig, rechts hoch.'], expl: 'Von vorn sieht man die Treppenstufen als Umriss. Die Kanten zwischen den Stufen sind sichtbar, es gibt keine verdeckten Kanten.' }),
    T('zei4', AN, 2, 'Winkel: Welche Vorderansicht passt?', { kind: 'iso2view', model: 'winkel', view: 'front', text: 'Welche Vorderansicht gehört zum Winkel? ' + ISOHINT, tips: ['Von vorn siehst du den Umriss der L-Form. Gibt es Kanten, die man nicht sieht?', 'Die Bohrung liegt im waagerechten Schenkel und ist von vorn nicht zu sehen: Sie erscheint als Strichlinie (verdeckte Kanten).'], expl: 'Die Bohrung im Fuß ist von vorn verdeckt und wird mit zwei Strichlinien dargestellt. Die Mittellinie der Bohrung ist eine Strich-Punkt-Linie.' }),
    T('zei5', AN, 2, 'Stufenblock: Welche Draufsicht passt?', { kind: 'iso2view', model: 'stufenblock', view: 'top', text: 'Welche Draufsicht gehört zum Stufenblock? Die Draufsicht schaut von oben auf den Körper. In der Draufsicht liegt die Vorderseite UNTEN. ' + ISOHINT, tips: ['Von oben siehst du zwei Höhen. Wo liegt die höhere Fläche, vorn oder hinten?', 'In der Draufsicht ist die Vorderseite des Körpers unten gezeichnet, die Rückseite oben.'], expl: 'Die höhere Fläche liegt links hinten. Zwischen den Höhen sieht man in der Draufsicht eine Kante (Volllinie), weil der Absatz sichtbar ist.' }),
    T('zei6', AN, 2, 'Winkel: Welche Seitenansicht passt?', { kind: 'iso2view', model: 'winkel', view: 'side', text: 'Welche Seitenansicht von links gehört zum Winkel? Du schaust von links auf den Körper, in der Isometrie ist das die nicht sichtbare Seite hinten links. ' + ISOHINT, tips: ['Von links siehst du die Stirnfläche des hohen Schenkels. Wie groß ist sie?', 'Die Bohrung im Fuß ist von links durch den hohen Schenkel verdeckt: Strichlinie.'], expl: 'Von links sieht man das hohe Quadrat des Schenkels. Die Bohrung im Fuß liegt dahinter und wird mit Strichlinien gezeichnet.' }),
    T('zei7', AN, 2, 'Brücke: Welche Draufsicht passt?', { kind: 'iso2view', model: 'bruecke', view: 'top', text: 'Welche Draufsicht gehört zum Körper mit Durchgang? ' + ISOHINT, tips: ['Von oben sieht man die Deckfläche. Was ist mit dem Durchgang darunter?', 'Der Durchgang ist von oben verdeckt und wird in der Draufsicht mit Strichlinien gezeichnet.'], expl: 'Der Durchgang liegt unter der geschlossenen Deckfläche. Seine Kanten sind verdeckt: Strichlinien.' }),
    T('zei8', AN, 3, 'Freier Körper: Welche Vorderansicht passt?', { kind: 'iso2view', model: 'rand', view: 'front', text: 'Welche Vorderansicht gehört zum gezeigten Körper? ' + ISOHINT, tips: ['Übertrage die Höhen der Spalten von vorn nach rechts in die Ansicht. Kanten dahinter erkennst du nur an den Höhen.', 'Sichtbare Kanten: Stufen zwischen vorderen und hinteren Flächen. Verdeckte Kanten: Strichlinie.'], expl: 'Nur die Vorderansicht passt zu den Höhen und Kanten des Körpers. Die anderen Bilder zeigen eine Stufe zu viel, zu wenig oder gespiegelt.' }),
    T('zei9', ER, 2, 'Treppenblock: Vorderansicht ergänzen', { kind: 'view3', model: 'staffel', given: ['top', 'side'], target: 'front', text: 'Draufsicht und Seitenansicht von links sind gegeben. Welche Vorderansicht gehört dazu?', tips: ['Die Vorderansicht liegt links von der Seitenansicht und über der Draufsicht. Die Breite kommt aus der Draufsicht, die Höhen aus der Seitenansicht.', 'Du schaust von vorn: die vorderen, niedrigen Stufen verdecken die dahinter liegenden höheren nicht. Der Umriss zeigt die höchste Höhe je Spalte.'], expl: 'Die Breite stimmt mit der Draufsicht überein, die Höhe mit der Seitenansicht. Der Umriss ist die höchste Stelle je Spalte; Kanten zwischen den Stufen sind sichtbar.' }),
    T('zei10', ER, 2, 'Treppenblock: Seitenansicht ergänzen', { kind: 'view3', model: 'staffel', given: ['front', 'top'], target: 'side', text: 'Vorderansicht und Draufsicht sind gegeben. Welche Seitenansicht von links gehört dazu?', tips: ['Die Seitenansicht liegt rechts neben der Vorderansicht: gleiche Höhe wie die Vorderansicht.', 'Die Tiefe liest du in der Draufsicht ab. Von links sieht man die höchste Stufe zuerst vor dem Hintergrund.'], expl: 'Höhen kommen aus der Vorderansicht, die Tiefe aus der Draufsicht. Von links sieht man die niedrigste Stufe vorn, die anderen verdeckt dahinter.' }),
    T('zei11', ER, 3, 'Freier Körper: Seitenansicht ergänzen', { kind: 'view3', model: 'rand', given: ['front', 'top'], target: 'side', text: 'Vorderansicht und Draufsicht sind gegeben. Welche Seitenansicht von links gehört dazu?', tips: ['Übertrage die Höhen aus der Vorderansicht und die Tiefen aus der Draufsicht. In der Seitenansicht ist die Vorderseite rechts.', 'Verdeckte Kanten ergeben Strichlinien. Prüfe, ob Alternativen zur Draufsicht passen.'], expl: 'Die richtige Seitenansicht passt zur Höhe aus der Vorderansicht und zur Tiefe aus der Draufsicht (vorn rechts, hinten links).' }),
    T('zei12', ER, 1, 'Treppe: Draufsicht zeichnen', { kind: 'edges', model: 'treppe', given: ['front'], target: 'top', text: 'Trage die Kanten der Draufsicht in das Raster ein. Tippen wechselt: leer, Volllinie, Strichlinie.', tips: ['In der Draufsicht siehst du jede Stufenkante von oben als Volllinie. Rand des Körpers nicht vergessen.', 'Es gibt keine verdeckten Kanten, nur Volllinien: Außenrand und zwei Linien zwischen den Stufen.'], expl: 'Außenrechteck plus je eine Linie an den Stufenkanten. Hinter der Treppe liegt nichts Verdecktes.' }),
    T('zei13', ER, 2, 'Winkel: Draufsicht zeichnen', { kind: 'edges', model: 'winkel', given: ['front'], target: 'top', text: 'Trage die Kanten der Draufsicht in das Raster ein. Tippen wechselt: leer, Volllinie, Strichlinie.', tips: ['Der Rand, die Kante des hohen Schenkels und die Bohrung sind von oben sichtbar.', 'Die Bohrung ist von oben sichtbar: ein Quadrat mit Volllinien. Nichts ist verdeckt.'], expl: 'Außenrand, Kante zwischen Fuß und hohem Schenkel und die Bohrung: alles von oben sichtbar, also Volllinien.' }),
    T('zei14', ER, 3, 'Nutenstein: Seitenansicht zeichnen', { kind: 'edges', model: 'nutenstein', given: ['front'], target: 'side', text: 'Trage die Kanten der Seitenansicht von links in das Raster ein. Tippen wechselt: leer, Volllinie, Strichlinie.', tips: ['Von links sind Fuß und Hals gleich tief. Die Kante zwischen Fuß und Hals ist sichtbar: Volllinie.', 'Nur die Bohrung liegt innen und ist von links verdeckt: zwei senkrechte Strichlinien. Der Umriss von Fuß und Hals bleibt Volllinie.'], expl: 'Umriss von Fuß und Hals und die Kante zwischen beiden sind sichtbar (Volllinien). Nur die Bohrung liegt innen: zwei senkrechte Strichlinien.' }),
    T('zei15', LB, 1, 'Mittellinie: Welche Linienart?', { kind: 'use2line', line: 'sp', pool: ['sp'], text: '', tips: ['Mittellinien markieren die Achse von Bohrungen und runden Teilen.', 'Die Linie besteht aus langen Strichen und einem Punkt dazwischen; sie ist schmal.'], expl: '' }),
    T('zei16', LB, 1, 'Sichtbare Kanten: Welche Verwendung?', { kind: 'line2use', line: 'breit', pool: ['breit'], text: '', tips: ['Die Linie ist die breiteste und durchgezogen.', 'Mit der breiten Volllinie zeichnet man alles, was man am Bauteil sieht.'], expl: '' }),
    T('zei17', LB, 2, 'Verdeckte Kanten: Welche Linienart?', { kind: 'use2line', line: 'strich', pool: ['strich'], text: '', tips: ['Verdeckte Kanten sind unterbrochen gezeichnet, damit man sie nicht mit sichtbaren verwechselt.', 'Gesucht ist die Linie aus gleichmäßigen Strichen mit Lücken, ohne Punkte.'], expl: '' }),
    T('zei18', LB, 1, 'Maßlinie: Welche Linienart?', { kind: 'rule', rule: 0, pool: [0], text: '', tips: ['Maßlinien dürfen nicht mit den Körperkanten verwechselt werden.', 'Sie sind dünn und durchgezogen.'], expl: '' }),
    T('zei19', LB, 1, 'Durchmesserzeichen', { kind: 'rule', rule: 3, pool: [3], text: '', tips: ['Das Zeichen sieht aus wie ein durchgestrichener Kreis.', 'Es steht vor der Maßzahl, nicht dahinter.'], expl: '' }),
    T('zei20', LB, 2, 'Maßzahl an senkrechter Maßlinie', { kind: 'rule', rule: 2, pool: [2], text: '', tips: ['Maßzahlen sollen von unten oder von rechts lesbar sein.', 'Bei senkrechten Maßlinien dreht man die Zahl um 90° nach links, so dass sie von rechts lesbar ist.'], expl: '' }),
    T('zei21', LB, 3, 'Doppelbemaßung', { kind: 'rule', rule: 5, pool: [5], text: '', tips: ['Überlege, wie leicht sich Widersprüche einschleichen, wenn ein Maß zweimal steht.', 'Eine gute Zeichnung enthält jedes Maß genau einmal.'], expl: '' }),
    T('zei22', MA, 1, 'Maßstab: Zeichnungsmaß berechnen', { kind: 'scale', level: 1, dir: 'z', scale: [1, 2], text: '', tips: ['M 1:2 heißt: Die Zeichnung ist halb so groß wie das Bauteil.', 'Zeichnungsmaß = Naturmaß geteilt durch 2.'], expl: '' }),
    T('zei23', MA, 2, 'Maßstab: Naturmaß berechnen', { kind: 'scale', level: 2, dir: 'n', text: '', tips: ['Bei Vergrößerung (z. B. 5:1) ist die Zeichnung größer als das Bauteil.', 'Naturmaß = Zeichnungsmaß mal Natur-Zahl durch Zeichnungs-Zahl (Beispiel M 5:1: durch 5 teilen).'], expl: '' }),
    T('zei24', MA, 2, 'Welcher Maßstab wurde verwendet?', { kind: 'scaleq', level: 2, text: '', tips: ['Maßstab = Zeichnungsmaß : Naturmaß.', 'Ist die Zeichnung kleiner als das Bauteil, ist es eine Verkleinerung (links die kleinere Zahl).'], expl: '' }),
    T('zei25', MA, 3, 'Maßstab: gemischte Rechnung', { kind: 'scale', level: 3, text: '', tips: ['Lies den Maßstab zuerst: Zeichnung : Natur.', 'Vergrößerung: Zeichnung = Natur mal Faktor. Verkleinerung: Zeichnung = Natur durch Faktor.'], expl: '' }),
    T('zei26', SC, 2, 'Winkel: Welcher Schnitt A–A?', { kind: 'schnitt', model: 'winkel', cy: 1, text: 'Der Winkel wird entlang der Linie A–A geschnitten. Die Pfeile zeigen die Blickrichtung (nach hinten). Welcher Schnitt A–A gehört dazu? Schnittflächen werden mit 45°-Linien schraffiert.', tips: ['Der Teil vor der Schnittebene wird weggenommen. Du siehst auf die Schnittfläche und dahinter.', 'Die Schnittebene geht durch die Bohrung: In der Schnittfläche ist dort eine Lücke (nicht schraffiert).'], expl: 'Die Schnittfläche ist schraffiert und zeigt den Fuß mit der Bohrungslücke und den hohen Schenkel. Hinter der Ebene liegende Kanten sind sichtbar.' }),
    T('zei27', SC, 2, 'Stufenblock: Welcher Schnitt A–A?', { kind: 'schnitt', model: 'stufenblock', cy: 1, text: 'Der Stufenblock wird entlang der Linie A–A geschnitten. Die Pfeile zeigen die Blickrichtung (nach hinten). Welcher Schnitt A–A gehört dazu?', tips: ['Schau auf die Schnittebene: Wie hoch ist der Körper dort, wie breit der Absatz?', 'Schraffiert wird nur, was in der Schnittebene wirklich Material ist. Dahinter sichtbare Stufen bleiben unschraffiert.'], expl: 'In der Schnittebene hat der Körper links den Absatz (zwei Würfel hoch) und rechts den niedrigen Teil. Dahinter sieht man die weitere Stufe als unschraffierte Fläche.' }),
    T('zei28', SC, 3, 'Nutenstein: Welcher Schnitt A–A?', { kind: 'schnitt', model: 'nutenstein', cy: 1, text: 'Der Nutenstein wird mittig entlang der Linie A–A geschnitten. Die Pfeile zeigen die Blickrichtung (nach hinten). Welcher Schnitt A–A gehört dazu?', tips: ['Die Schnittebene liegt in der Mitte, genau durch die Bohrung.', 'Die Bohrung ist in der Schnittfläche eine unschraffierte Lücke in der Mitte, die Fuß und Hals durchläuft.'], expl: 'Fuß breit, Hals schmal, die Bohrung als Lücke durch beide. Die Schnittfläche ist schraffiert, dahinter liegende Kanten sind sichtbar.' }),
    T('zei29', AN, 1, 'Anordnung: Was liegt links neben der Vorderansicht?', { kind: 'know', q: 'Welche Ansicht liegt bei der Projektionsmethode 1 (Europa) LINKS neben der Vorderansicht?', right: 'Die Seitenansicht von rechts', wrong: ['Die Seitenansicht von links', 'Die Draufsicht, nach links geklappt', 'Die Untersicht'], tips: ['Du blickst von rechts auf den Körper. Die Ansicht wird auf die gegenüberliegende Seite der Vorderansicht gelegt.', 'Die Seitenansicht von links liegt rechts neben der Vorderansicht, die Seitenansicht von rechts deshalb links davon.'], expl: 'Bei der Projektionsmethode 1 liegt jede Ansicht auf der entgegengesetzten Seite des Blickpunkts: Die Ansicht von rechts links neben der Vorderansicht, die Ansicht von links rechts daneben.' }),
    T('zei30', AN, 1, 'Platte mit Zapfen: Welche Draufsicht passt?', { kind: 'iso2view', model: 'zapfen', view: 'top', text: 'Welche Draufsicht gehört zur Platte mit Zapfen? In der Draufsicht liegt die Vorderseite UNTEN. ' + ISOHINT, tips: ['Von oben siehst du die Platte und darauf den Zapfen. Wo sitzt der Zapfen auf der Platte?', 'Der Zapfen sitzt mittig. Seine Kanten sind von oben sichtbar, es gibt keine verdeckten Kanten.'], expl: 'Von oben erscheint die Platte als Quadrat mit dem Zapfen als kleinerem Quadrat in der Mitte. Beide Umrisse sind sichtbar: Volllinien.' }),
    T('zei31', AN, 2, 'Block mit Nut: Welche Vorderansicht passt?', { kind: 'iso2view', model: 'prisma', view: 'front', text: 'Welche Vorderansicht gehört zum Block mit durchgehender Nut? ' + ISOHINT, tips: ['Die Nut läuft durch die ganze Tiefe. Wie sieht man sie von vorn?', 'Von vorn erscheint die Nut als Einschnitt in der oberen Kante; sie ist sichtbar, darum Volllinien.'], expl: 'Die durchgehende Nut ist von vorn als Einschnitt im Umriss zu sehen. Es sind keine Strichlinien nötig, weil nichts verdeckt ist.' }),
    T('zei32', ER, 2, 'Block mit Nut: Draufsicht zeichnen', { kind: 'edges', model: 'prisma', given: ['front'], target: 'top', text: 'Trage die Kanten der Draufsicht in das Raster ein. Tippen wechselt: leer, Volllinie, Strichlinie.', tips: ['Von oben siehst du den Rand des Blocks und die beiden Kanten der Nut. Die Nut läuft durch die ganze Tiefe.', 'Die Nutkanten sind von oben sichtbar und laufen von vorn bis hinten: zwei durchgehende Volllinien. Verdeckte Kanten gibt es nicht.'], expl: 'Außenrechteck plus zwei Linien für die Nutkanten, die durch die ganze Tiefe laufen. Alles ist von oben sichtbar: Volllinien.' }),
    T('zei33', ER, 3, 'Nutenstein: Seitenansicht ergänzen', { kind: 'view3', model: 'nutenstein', given: ['front', 'top'], target: 'side', text: 'Vorderansicht und Draufsicht sind gegeben. Welche Seitenansicht von links gehört dazu?', tips: ['Die Höhen kommen aus der Vorderansicht, die Tiefe aus der Draufsicht. In der Seitenansicht ist die Vorderseite rechts.', 'Fuß und Hals haben verschiedene Breiten, die du in der Draufsicht ablesen kannst. Prüfe, ob die Alternative zur Draufsicht passt.'], expl: 'Von links sieht man den Fuß vorn und darüber den zurückgesetzten Hals; die Kante dazwischen ist sichtbar (Volllinie). Höhen und Tiefen passen zu Vorderansicht und Draufsicht. Die Bohrung liegt innen und wird gestrichelt gezeichnet.' }),
    T('zei34', LB, 1, 'Quadratzeichen', { kind: 'rule', rule: 12, pool: [12], text: '', tips: ['Das Zeichen sieht aus wie das Bild, das es beschreibt.', 'Es steht wie das Durchmesserzeichen vor der Maßzahl.'], expl: '' }),
    T('zei35', LB, 2, 'Mittellinien: Wie weit nach außen?', { kind: 'rule', rule: 14, pool: [14], text: '', tips: ['Mittellinien sollen auf der Zeichnung gut zu erkennen sein.', 'Sie enden nicht genau an der Kante, sondern überstehen sie leicht.'], expl: '' }),
    T('zei36', SC, 3, 'Wellenabsatz: Welcher Schnitt A–A?', { kind: 'schnitt', model: 'wellenabsatz', cy: 1, text: 'Der Wellenabsatz (vereinfacht mit quadratischem Querschnitt) wird mittig entlang der Linie A–A geschnitten. Die Pfeile zeigen die Blickrichtung (nach hinten). Welcher Schnitt A–A gehört dazu?', tips: ['Die Schnittebene liegt in der Mitte, genau durch die Zentrierbohrung am Ende.', 'Die Zentrierbohrung ist in der Schnittfläche eine unschraffierte Lücke. Der dicke Bund und der dünne Zapfen haben verschiedene Höhen.'], expl: 'Die Schnittfläche zeigt den breiten Bund mit der Bohrung als Lücke und den schmalen Zapfen. Sie ist schraffiert, dahinter sichtbare Kanten bleiben unschraffiert.' }),
    /* ---- Berufsschulstoff (Lernfeld 5.3 Blockschaltbild, Lernfeld 8.1 technische Darstellungen), v. a. Wissensfragen ohne Bild */
    T('zei37', BL, 1, 'A-Formate: Blatt teilen', { kind: 'know', q: 'Ein Zeichenblatt im Format A3 (297 mm × 420 mm) wird quer zur langen Seite genau in der Mitte durchgeschnitten. Welches Format haben die beiden Hälften?', right: 'A4 (210 mm × 297 mm)', wrong: ['A5 (148 mm × 210 mm)', 'A2 (420 mm × 594 mm)', 'B4 (250 mm × 353 mm)'], tips: ['Bei der A-Reihe entsteht das nächstkleinere Format immer durch Halbieren der langen Seite. Das Seitenverhältnis 1 : √2 bleibt dabei gleich.', 'Die kurze Seite des A3-Blatts (297 mm) wird zur langen Seite des neuen Blatts, die halbierte lange Seite (210 mm) zur kurzen.'], expl: 'Jede Halbierung der langen Seite ergibt das nächstkleinere A-Format: A3 wird zu A4. Ausgangspunkt der Reihe ist A0 mit 1 m² Fläche. Das Seitenverhältnis bleibt immer 1 : √2.' }),
    /* PRUEFEN P1: Liniengruppe 0,7 mit schmaler Linie 0,35 mm (Verhältnis 2 : 1 nach ISO 128-20). Im Unterricht wird mit Druckbleistiften 0,3 / 0,5 / 0,7 gezeichnet: Ist die genormte Zahl 0,35 hier gewünscht, oder gilt im Unterricht 0,5 für die schmale Linie? */
    T('zei38', BL, 2, 'Liniengruppe und Linienbreiten', { kind: 'know', q: 'In einer Zeichnung gilt die Liniengruppe 0,7: Die breite Volllinie ist 0,7 mm breit. Wie breit ist dann die schmale Volllinie?', right: '0,35 mm', wrong: ['0,25 mm', '0,5 mm', '0,7 mm'], tips: ['Breite und schmale Linien stehen in der Norm in einem festen Verhältnis zueinander, das für alle Liniengruppen gleich ist.', 'Das Verhältnis breit : schmal ist 2 : 1. Innerhalb einer Zeichnung verwendet man nur eine Liniengruppe.'], expl: 'Breite und schmale Linien stehen im Verhältnis 2 : 1. Bei der Liniengruppe 0,7 ist die breite Linie 0,7 mm und die schmale Linie 0,35 mm breit. Innerhalb einer Zeichnung gilt nur eine Liniengruppe.' }),
    T('zei39', DA, 2, 'Schrägbild: Länge der Tiefenkante', { kind: 'know', q: 'Ein Würfel mit 40 mm Kantenlänge wird in der Kabinettprojektion gezeichnet. Die Vorderfläche liegt unverzerrt in der Zeichenebene. Wie lang wird die nach hinten laufende Kante in der Zeichnung?', right: '20 mm', wrong: ['40 mm', '28 mm', '10 mm'], tips: ['Bei der Kabinettprojektion bleibt die Vorderansicht in wahrer Größe. Die Tiefe wird schräg nach hinten gezeichnet, meist unter 45°.', 'Damit das Bild nicht zu tief wirkt, wird die Tiefenachse verkürzt: Es bleibt nur ein bestimmter Bruchteil der wirklichen Länge übrig.'], expl: 'In der Kabinettprojektion werden Breite und Höhe maßstäblich gezeichnet, die Tiefenachse läuft unter 45° und wird auf die Hälfte verkürzt. Aus 40 mm Tiefe werden 20 mm in der Zeichnung. In der Isometrie dagegen sind alle drei Achsen gleich lang.' }),
    /* PRUEFEN P2: In der Mitschrift wird die Explosionszeichnung auch Anordnungsplan genannt; im Elektrobereich heißt Anordnungsplan sonst die Lage von Geräten im Raum. Begriff so stehen lassen oder weglassen? */
    T('zei40', DA, 1, 'Darstellung einer Baugruppe', { kind: 'know', q: 'Welche Zeichnung zeigt Lage und Aufbau einer Baugruppe, indem die Einzelteile entlang ihrer Achsen auseinandergezogen dargestellt werden?', right: 'Explosionszeichnung', wrong: ['Zusammenbauzeichnung', 'Dreitafelprojektion', 'Halbschnittzeichnung'], tips: ['Gesucht ist eine anschauliche Darstellung, die zeigt, in welcher Reihenfolge und Lage die Einzelteile zusammengesetzt werden.', 'Die Teile liegen mit Abstand hintereinander auf gemeinsamen Achsen, so als wäre die Baugruppe auseinandergesprengt.'], expl: 'Die Explosionszeichnung zeigt Lage und Aufbau einer Baugruppe und oft auch ihre Funktion. Gefertigt wird nach ihr nicht: Die Einzelteile bekommen eigene Zeichnungen.' }),
    T('zei41', DA, 1, 'Blockschaltbild eines Netzteils lesen', { kind: 'know', q: 'In welcher Reihenfolge stehen die Blöcke im Blockschaltbild eines einfachen Netzteils vom Netzanschluss bis zum Verbraucher?', right: 'Transformator, Gleichrichter, Siebung, Stabilisierung', wrong: ['Gleichrichter, Transformator, Stabilisierung, Siebung', 'Transformator, Siebung, Gleichrichter, Stabilisierung', 'Stabilisierung, Siebung, Gleichrichter, Transformator'], tips: ['Ein Blockschaltbild liest man in Richtung des Signal- oder Energieflusses, meist von links (Eingang) nach rechts (Ausgang).', 'Die Netzspannung wird zuerst auf einen passenden Wert transformiert und dann gleichgerichtet. Die Restwelligkeit glättet die Siebung, erst am Ende regelt die Stabilisierung auf einen festen Wert.'], expl: 'Netztransformator, Gleichrichter, Siebung und Stabilisierung folgen in dieser Reihenfolge. Im Blockschaltbild stehen sie als Rechtecke, die Linien mit Pfeilen zeigen den Fluss von Energie und Signal. Wie die Blöcke innen aufgebaut sind, zeigt erst der Schaltplan.' }),
    T('zei42', SC, 2, 'Symmetrisches Hohlteil darstellen', { kind: 'know', q: 'Ein symmetrisches, hohles Bauteil soll in einer einzigen Ansicht auf der einen Seite die Außenform und auf der anderen Seite den inneren Aufbau zeigen. Welche Schnittart wählt man?', right: 'Halbschnitt', wrong: ['Vollschnitt', 'Teilschnitt', 'Rückansicht'], tips: ['Eine Hälfte soll von außen, die andere von innen gezeigt werden. Das geht nur bei Teilen, die sich selbst spiegeln.', 'Die Symmetrielinie (Strich-Punkt-Linie) trennt die geschnittene Hälfte von der Ansichtshälfte.'], expl: 'Beim Halbschnitt ist eine Hälfte des symmetrischen Teils geschnitten und die andere als Ansicht gezeichnet, die Mittellinie trennt beide. Beim Vollschnitt wird das ganze Teil geschnitten, beim Teilschnitt nur ein kleiner Ausschnitt.' }),
    /* PRUEFEN P3: Begrenzung des Teilschnitts mit Freihandlinie (Zickzacklinie ist ebenfalls zulässig, ISO 128-34). Reicht die Freihandlinie als einzige Antwort? */
    T('zei43', SC, 2, 'Einzelne Bohrung im Gehäuse zeigen', { kind: 'know', q: 'Bei einem Gehäuse soll nur eine einzelne Bohrung im Inneren gezeigt werden, der Rest der Ansicht bleibt unverändert. Mit welcher Linie begrenzt man den ausgebrochenen Bereich?', right: 'Freihandlinie, schmal', wrong: ['Strichlinie, schmal', 'Strich-Punkt-Linie, schmal', 'Volllinie, breit'], tips: ['Gesucht ist der Teilschnitt (Ausbruch): Nur ein Stück der Wand wird weggebrochen gedacht.', 'Die Grenze des Ausbruchs sieht aus wie eine Bruchkante und wird ohne Lineal gezeichnet.'], expl: 'Beim Teilschnitt (Ausbruch) wird nur ein kleiner Bereich geschnitten. Seine Grenze zeichnet man als Freihandlinie (schmal), ähnlich einer Bruchkante. Die geschnittene Fläche wird schraffiert.' }),
    T('zei44', LB, 3, 'Gestreckte Länge eines Biegeteils', { kind: 'know', q: 'Ein Winkel wird aus 2 mm dickem Blech um 90° gebogen. Der Innenradius beträgt 3 mm, die Schenkel sind außen 40 mm und 30 mm lang. Für den Zuschnitt rechnet man mit der Länge der mittleren Faser. Wie lang ist das gestreckte Blech?', right: '66,3 mm', wrong: ['70,0 mm', '67,9 mm', '64,7 mm'], tips: ['Zerlege den Zuschnitt in zwei gerade Stücke und ein Bogenstück. Die geraden Stücke sind kürzer als die Außenmaße, weil die Rundung schon mitzählt.', 'Der Radius der mittleren Faser ist Innenradius plus halbe Blechdicke. Die Bogenlänge für 90° ist ein Viertel des Kreisumfangs. Von jedem Außenmaß ziehst du Innenradius plus Blechdicke ab.'], expl: 'Gerade Stücke: 40 mm − 5 mm = 35 mm und 30 mm − 5 mm = 25 mm. Mittlere Faser: r = 3 mm + 1 mm = 4 mm, Bogen = π · 4 mm / 2 = 6,3 mm. Zuschnitt = 35 mm + 25 mm + 6,3 mm = 66,3 mm.' }),
    /* ---- Berufsschulstoff (Schaltzeichen und Schaltplanarten, Elektroinstallation), Wissensfragen ohne Bild */
    T('zei45', DA, 1, 'Norm für Schaltzeichen', { kind: 'know', q: 'Nach welcher Norm werden die grafischen Symbole für Schaltpläne der Elektrotechnik festgelegt?', right: 'DIN EN 60617', wrong: ['DIN EN ISO 128', 'DIN EN 60204', 'DIN 476'], tips: ['Die Zeichen für Schalter, Lampen, Steckdosen und andere Betriebsmittel sind genormt, damit jeder Schaltplan überall gleich gelesen wird.', 'Die gesuchte Norm trägt die Nummer 60617. Die Norm ISO 128 gilt für technische Zeichnungen allgemein, nicht für Schaltzeichen.'], expl: 'Grafische Symbole für Schaltpläne stehen in der Normenreihe DIN EN 60617. Ein Schaltzeichen ist ein genormtes Symbol, mit dem ein elektrisches Betriebsmittel im Plan dargestellt wird, zum Beispiel eine Glühlampe oder eine Schutzkontaktsteckdose. Die Größe richtet sich nach dem Zeichenblatt, die Proportionen bleiben dabei erhalten.' }),
    T('zei46', DA, 1, 'Farben der Leiter in der Installation', { kind: 'know', q: 'Welche Zuordnung von Leiter und Isolierfarbe ist in der Elektroinstallation richtig?', right: 'L1 braun, L2 schwarz, L3 grau', wrong: ['L1 blau, L2 schwarz, L3 grau', 'L1 braun, L2 grün-gelb, L3 grau', 'L1 braun, L2 schwarz, L3 blau'], tips: ['Die Außenleiter werden der Reihe nach nummeriert, und jede Nummer hat eine feste Isolierfarbe. So erkennt man einen Leiter, ohne ihn zu messen.', 'Zwei Farben sind schon vergeben: blau für den Neutralleiter N und grün-gelb für den Schutzleiter PE. Für die drei Außenleiter bleiben die übrigen Farben, braun gehört zu L1.'], expl: 'Die Außenleiter sind L1 braun, L2 schwarz und L3 grau. Der Neutralleiter N ist blau, der Schutzleiter PE grün-gelb. Blau und grün-gelb dürfen deshalb nie für einen Außenleiter verwendet werden.' }),
    /* PRUEFEN P1: Die Mitschrift nennt nur Schaltgeräte (Kennbuchstabe unleserlich) und Meldeleuchte (P). Hier sind nur Motor M, Transformator T und Klemme X abgefragt. Welche Kennbuchstaben gelten im Unterricht für Schalter und Meldeleuchte (Q, S, P oder H, nach DIN EN 61346-2 oder älter)? */
    T('zei47', DA, 2, 'Kennbuchstaben von Betriebsmitteln', { kind: 'know', q: 'Welche Zuordnung von Betriebsmittel und Kennbuchstabe stimmt in einem Schaltplan?', right: 'Motor: M, Transformator: T, Klemme: X', wrong: ['Motor: T, Transformator: M, Klemme: X', 'Motor: X, Transformator: T, Klemme: M', 'Motor: M, Transformator: X, Klemme: T'], tips: ['Jedes Betriebsmittel im Schaltplan bekommt einen Kennbuchstaben mit Zählnummer, zum Beispiel M1. Der Buchstabe steht für die Art des Betriebsmittels.', 'Der Motor trägt als Kennbuchstaben seinen Anfangsbuchstaben. Der Transformator bekommt T, und die Klemmstelle als Verbindungsstelle trägt X.'], expl: 'Die Kennbuchstaben sind M für Motoren, T für Transformatoren und X für Klemmen und andere Verbindungsstellen. Mit der Zählnummer ergeben sich Kennzeichen wie M1, T1 oder X1; so lässt sich jedes Betriebsmittel im Plan eindeutig benennen.' }),
    T('zei48', DA, 2, 'Aufgabe des PEN-Leiters', { kind: 'know', q: 'Welche beiden Aufgaben übernimmt ein PEN-Leiter?', right: 'Rückleiter (N) und Schutzleiter (PE) zugleich', wrong: ['Außenleiter (L) und Rückleiter (N) zugleich', 'Außenleiter (L) und Schutzleiter (PE) zugleich', 'Zwei Außenleiter (L1 und L2) zugleich'], tips: ['Der Name setzt sich aus den Kurzzeichen von zwei Leitern zusammen, deren Aufgaben der eine Leiter gemeinsam erfüllt.', 'Der Schutzleiter PE leitet mögliche Körperströme zur Erde ab, der Neutralleiter N führt den Strom zurück. Der Außenleiter gehört nicht zu den beiden Aufgaben.'], expl: 'Der PEN-Leiter vereint die Funktionen von Neutralleiter N (Rückleitung des Stroms) und Schutzleiter PE (leitet mögliche Körperströme zur Erde ab). Er ist grün-gelb gekennzeichnet, an den Enden zusätzlich blau.' }),
    /* PRUEFEN P2: Plan-Arten (zei49 bis zei51): Die Mitschrift nennt nur die Namen (Übersichtsschaltplan, Stromlaufplan aufgelöst und zusammenhängend, Installationsplan) und einpolig/mehrpolig. Die Erklärungen sind allgemeines Fachwissen in eigenen Worten; bitte gegen den Unterricht prüfen. */
    T('zei49', DA, 1, 'Plan für die Lage im Gebäude', { kind: 'know', q: 'Welcher Plan zeigt, an welcher Stelle im Raum Schalter, Steckdosen und Leuchten sitzen und wo die Leitungen verlegt werden?', right: 'Installationsplan', wrong: ['Übersichtsschaltplan', 'Stromlaufplan in aufgelöster Darstellung', 'Blockschaltbild'], tips: ['Gesucht ist ein Plan, der wie ein Grundriss aufgebaut ist und die Lage der Betriebsmittel im Gebäude zeigt.', 'Wie ein Stromkreis funktioniert, erkennt man in diesem Plan nur wenig. Dafür sieht man, wo etwas sitzt und wo die Leitungen entlanglaufen.'], expl: 'Der Installationsplan zeigt Lage und Leitungsführung der Betriebsmittel im Gebäude. Wie die Stromkreise arbeiten, zeigen die anderen Schaltplanarten: der Übersichtsschaltplan im Überblick, der Stromlaufplan mit allen Einzelheiten.' }),
    T('zei50', DA, 2, 'Einpolige Darstellung im Schaltplan', { kind: 'know', q: 'Mehrere Leiter eines Stromkreises werden vereinfacht durch eine einzige Linie gezeichnet. Wie nennt man diese Darstellungsart?', right: 'Einpolige Darstellung', wrong: ['Mehrpolige Darstellung', 'Aufgelöste Darstellung', 'Zusammenhängende Darstellung'], tips: ['Gesucht ist die vereinfachte Zeichenweise, die man vor allem im Übersichtsschaltplan findet. Es geht darum, wie viele Linien je Verbindung gezeichnet werden.', 'Bei der ausführlichen Darstellung bekommt jeder Leiter seine eigene Linie. Die vereinfachte Darstellung fasst mehrere Leiter zu einer Linie zusammen.'], expl: 'In der einpoligen Darstellung steht eine Linie für alle Leiter einer Verbindung; das spart Platz und zeigt den Zusammenhang im Überblick. In der mehrpoligen Darstellung wird jeder Leiter einzeln gezeichnet.' }),
    T('zei51', DA, 2, 'Stromlaufplan in aufgelöster Darstellung', { kind: 'know', q: 'In welchem Plan werden die Teile eines Betriebsmittels, zum Beispiel Spule und Kontakte eines Schützes, getrennt gezeichnet und nur über das gleiche Kennzeichen (K1) zugeordnet?', right: 'Stromlaufplan in aufgelöster Darstellung', wrong: ['Stromlaufplan in zusammenhängender Darstellung', 'Übersichtsschaltplan', 'Installationsplan'], tips: ['Das Betriebsmittel wird gewissermaßen in seine Teile aufgelöst. Die Teile stehen dort, wo sie im Stromweg gebraucht werden.', 'Zusammengehörige Teile erkennt man am gleichen Kennzeichen. Wären die Teile mit einer Wirkverbindung nebeneinander gezeichnet, wäre es die zusammenhängende Darstellung.'], expl: 'Im Stromlaufplan in aufgelöster Darstellung sind die Betriebsmittel in ihre Teile zerlegt und so angeordnet, dass die Strompfade übersichtlich verlaufen. Dass etwa Spule und Kontakte zusammengehören, zeigt allein das gemeinsame Kennzeichen.' }),
    T('zei52', DA, 3, 'Ausschaltung mit Steckdose: Welche Leiter?', { kind: 'know', q: 'Eine Leuchte wird über einen einpoligen Ausschalter geschaltet, im selben Stromkreis hängt eine Schutzkontaktsteckdose. Was ist richtig?', right: 'Zur Steckdose gehen L, N und PE; der Ausschalter unterbricht nur L', wrong: ['Zur Steckdose gehen nur L und N; der Ausschalter unterbricht L und N', 'Zur Steckdose gehen L, N und PE; der Ausschalter unterbricht L, N und PE', 'Zur Steckdose gehen nur L und PE; der Ausschalter unterbricht nur L'], tips: ['Überlege, was ein Verbraucher zum Betrieb braucht (Hin- und Rückleiter) und was die Schutzkontaktsteckdose zusätzlich für den Schutz benötigt.', 'Ein einpoliger Schalter hat nur einen Schaltkontakt und gehört in den Außenleiter. N und PE werden nicht geschaltet, der Schutzleiter schon gar nicht, weil er im Fehlerfall Körperströme ableiten muss.'], expl: 'Eine Schutzkontaktsteckdose braucht den Außenleiter L, den Neutralleiter N und den Schutzleiter PE. Ein einpoliger Ausschalter unterbricht nur den Außenleiter zur Leuchte; N und PE werden mitgeführt, und der Schutzleiter wird nie geschaltet.' }),
    /* ---- Berufsschulstoff (Lernfeld 8.1: Normschrift; Mitschrift E2: Kennbuchstaben), Wissensfragen ohne Bild. Neue Aufgaben stehen hinten, die Nummern der bisherigen bleiben. */
    /* PRUEFEN P4: Normschrift nach DIN EN ISO 3098 (zei53 bis zei55): Schriftform B mit Linienbreite d = h/10 (Schriftform A: h/14), Nenngrößen 2,5 / 3,5 / 5 / 7 / 10 mm (Stufung Wurzel 2), Zeichenabstand a = 2 · d. Die Mitschrift nennt nur „Abstand = 2 Linienbreiten“ und die Stufung; die übrigen Werte sind aus der Norm ergänzt. Wird im Unterricht Schriftform B (gerade oder kursiv) verwendet? */
    T('zei53', BL, 1, 'Normschrift: Breite des Schriftstrichs', { kind: 'know', q: 'Ein Schriftfeld wird in Normschrift, Schriftform B, mit der Schrifthöhe h = 5 mm beschriftet. Wie breit ist der Schriftstrich (Linienbreite d)?', right: '0,5 mm', wrong: ['0,35 mm', '0,7 mm', '1,0 mm'], tips: ['Bei der Normschrift hängt die Linienbreite fest an der Schrifthöhe h. Für die Schriftform B ist es ein glatter Bruchteil von h.', 'Bei Schriftform B ist der Schriftstrich ein Zehntel der Schrifthöhe, bei Schriftform A ein Vierzehntel.'], expl: 'Schriftform B: d = h : 10 = 5 mm : 10 = 0,5 mm. Bei Schriftform A wäre d = h : 14, also etwa 0,36 mm. Alle anderen Maße der Normschrift, zum Beispiel der Abstand der Zeichen, werden in Vielfachen von d angegeben.' }),
    T('zei54', BL, 2, 'Normschrift: Nenngröße aus der Reihe', { kind: 'know', q: 'Die Schrifthöhen der Normschrift sind wie die A-Formate gestuft. Welche Nenngröße folgt in der Reihe direkt auf 3,5 mm?', right: '5 mm', wrong: ['4 mm', '4,5 mm', '7 mm'], tips: ['Bei den A-Formaten wächst jede Seite von einem Format zum nächsten um den Faktor Wurzel 2, also etwa 1,4. Dieselbe Stufung gilt für die Schrifthöhen.', 'Rechne 3,5 mm mal 1,41 und runde auf die genormte Größe. Die Reihe beginnt bei 2,5 mm.'], expl: 'Die Nenngrößen der Normschrift sind 2,5 – 3,5 – 5 – 7 – 10 – 14 – 20 mm. Jede Stufe ist etwa um den Faktor Wurzel 2 (1,41) größer: 3,5 mm · 1,41 ≈ 4,9 mm, genormt 5 mm. So bleibt eine Beschriftung lesbar, wenn eine Zeichnung von A3 auf A4 verkleinert wird: Aus 5 mm werden etwa 3,5 mm.' }),
    T('zei55', BL, 3, 'Normschrift: Abstand der Zeichen', { kind: 'know', q: 'Ein Schriftfeld wird in Normschrift, Schriftform B, mit h = 7 mm beschriftet. Wie groß ist nach der Norm der Abstand zwischen zwei Schriftzeichen eines Wortes?', right: '1,4 mm', wrong: ['0,7 mm', '2,1 mm', '3,5 mm'], tips: ['Alle Abstände der Normschrift werden in Linienbreiten d angegeben. Bestimme zuerst d für Schriftform B.', 'Bei Schriftform B ist d = h : 10. Der Abstand zwischen zwei Zeichen beträgt zwei Linienbreiten.'], expl: 'Linienbreite d = 7 mm : 10 = 0,7 mm. Der Zeichenabstand beträgt 2 · d = 1,4 mm. Eine Linienbreite allein (0,7 mm) wäre zu eng, die Zeichen würden zusammenlaufen.' }),
    /* PRUEFEN P5: zei56 Kennbuchstaben nach DIN EN 81346-2: Q für Leistungsschalter, Schütz und Motorschutzschalter (Energiefluss schalten), P für Meldeleuchte und Anzeige. In älteren Plänen nach DIN 40719 steht für Meldeleuchten noch H und für Schütze K. Gilt im Unterricht die neue Norm? */
    T('zei56', DA, 2, 'Kennbuchstaben Q und P', { kind: 'know', q: 'In einem Schaltplan nach DIN EN 81346-2 bekommt jedes Betriebsmittel einen Kennbuchstaben nach seiner Aufgabe. Welche Zuordnung stimmt?', right: 'Leistungsschalter: Q, Meldeleuchte: P', wrong: ['Leistungsschalter: P, Meldeleuchte: Q', 'Leistungsschalter: X, Meldeleuchte: M', 'Leistungsschalter: T, Meldeleuchte: X'], tips: ['Nach der aktuellen Norm richtet sich der Kennbuchstabe nach der Aufgabe: Was tut das Betriebsmittel mit Energie oder Information?', 'Ein Leistungsschalter schaltet einen Energiefluss, eine Meldeleuchte stellt eine Information dar. M, T und X sind schon für Motor, Transformator und Klemme vergeben.'], expl: 'Q steht für Betriebsmittel, die einen Energiefluss schalten, zum Beispiel Leistungsschalter, Schütz oder Motorschutzschalter. P steht für Betriebsmittel, die eine Information darstellen, zum Beispiel Meldeleuchte oder Anzeige. Mit Zählnummer ergeben sich Kennzeichen wie Q1 oder P1. In älteren Plänen findet man für Meldeleuchten noch den Buchstaben H.' })
  ];
  /* Zusatz-Pools für den Trainer (mehr Abwechslung als die feste Aufgabe) */
  const poolById = { zei15: ['sp', 'schmal', 'spb', 'zwei', 'frei'], zei16: ['breit', 'schmal', 'strich', 'sp', 'spb', 'frei', 'zwei'], zei17: ['strich', 'breit', 'schmal', 'sp'],
    zei18: [0, 1, 7, 9, 10], zei19: [3, 4], zei20: [2, 1, 10], zei21: [5, 6, 8, 11], zei34: [12, 3, 4], zei35: [14, 13] };
  tasks.forEach(t => { if (poolById[t.id]) t.trainPool = poolById[t.id]; });

  /* Fertige Beispiele (Reiter Beispiele, ?bsp) */
  const examples = [
    { id: 'winkel', title: 'Winkel mit Bohrung in drei Ansichten', model: 'winkel', dim: true, notes: [
      'Die Vorderansicht (Mitte) zeigt die L-Form. Die Bohrung im Fuß ist von vorn nicht zu sehen: zwei Strichlinien (verdeckte Kanten) und eine Mittellinie (Strich-Punkt).',
      'Die Draufsicht liegt unter der Vorderansicht. Die Bohrung ist von oben sichtbar, darum Volllinien und ein Mittellinienkreuz. In der Draufsicht ist die Vorderseite unten.',
      'Die Seitenansicht von links liegt rechts neben der Vorderansicht: Von links sieht man nur den hohen Schenkel. Die Bohrung liegt dahinter und ist gestrichelt.',
      'Jedes Maß steht nur einmal: Breite und Höhe an der Vorderansicht, die Tiefe an der Draufsicht. Die Seitenansicht bleibt ohne Maße.'] },
    { id: 'stufenblock', title: 'Stufenblock', model: 'stufenblock', dim: true, notes: [
      'Alle Kanten sind von vorn oder oben sichtbar: es gibt keine Strichlinien.',
      'In der Vorderansicht sieht man den Absatz, aber nicht, wie tief er ist. Das zeigt erst die Draufsicht: Zusammen ergeben die Ansichten den Körper eindeutig.',
      'Wo zwei Flächen in verschiedener Höhe aneinanderstoßen, entsteht eine Kante (Volllinie). Wo zwei Flächen in einer Ebene liegen, wird keine Linie gezeichnet.'] },
    { id: 'nutenstein', title: 'Nutenstein mit Bohrung', model: 'nutenstein', dim: true, notes: [
      'Breiter Fuß und schmaler Hals, die Bohrung geht durch beides. Die Bohrung ist in Vorder- und Seitenansicht verdeckt und wird gestrichelt gezeichnet.',
      'In der Draufsicht sieht man den Hals auf dem Fuß und die Bohrung als Quadrat (Volllinien) mit Mittellinienkreuz.',
      'In der Seitenansicht von links sind Fuß und Hals gleich tief. Die Kante zwischen Fuß und Hals ist sichtbar und wird als Volllinie gezeichnet; gestrichelt ist nur die Bohrung.'] },
    { id: 'welle', title: 'Wellenabsatz im Schnitt', model: 'wellenabsatz', cy: 1, section: true, notes: [
      'Die Schnittebene geht mitten durch den Körper. Der vordere Teil ist weggenommen, man blickt auf die Schnittfläche.',
      'Die Schnittfläche wird mit Volllinien schmal unter 45° schraffiert. Die Zentrierbohrung am linken Ende bleibt als unschraffierte Lücke.',
      'Im Schnitt werden keine verdeckten Kanten gezeichnet. Die Absatzkante zwischen Bund und Zapfen ist sichtbar.',
      'Die Welle ist hier vereinfacht mit quadratischem Querschnitt gezeichnet; eine runde Welle sieht in der Längsschnitt-Ansicht genauso aus.'] },
    { id: 'prisma', title: 'Block mit durchgehender Nut', model: 'prisma', dim: true, notes: [
      'Die Nut zeigt sich nur in der Vorderansicht als Einschnitt (Volllinien). In der Draufsicht laufen zwei Linien durch.',
      'In der Seitenansicht von links liegt die Nutsohle hinter der Stirnfläche: Strichlinie über die ganze Breite.',
      'Mit diesen drei Ansichten ist der Körper eindeutig dargestellt.'] }
  ];

  const sections = [];
  root.ZEI_DATA = { models, lines, rules, tasks, examples, cats: [AN, ER, LB, MA, SC, BL, DA], sections };
  root.ZEI_TASKS = tasks.map(t => ({ id: t.id, cat: t.cat, title: t.title, level: t.level }));
  if (typeof module !== 'undefined' && module.exports) module.exports = { DATA: root.ZEI_DATA, TASKS: root.ZEI_TASKS };
})(typeof window !== 'undefined' ? window : globalThis);
